args.query:
SELECT DISTINCT statusId FROM results WHERE resultId IN (
    SELECT resultId FROM results r 
    JOIN train_labels t ON r.driverId = t.driverId AND r.date = t.date
    WHERE t.did_not_finish = 1
);

SELECT statusId, COUNT(*) as count FROM results WHERE resultId IN (
    SELECT resultId FROM results r 
    JOIN train_labels t ON r.driverId = t.driverId AND r.date = t.date
    WHERE t.did_not_finish = 1
) GROUP BY statusId ORDER BY count DESC;
